# Flood extent styling for 100-year return period.
# Values represent model-consensus classes: 0 (dry/no flood) to 6 (highest consensus).
CLASS
    NAME "Dry / no flood (0)"
    EXPRESSION ([pixel] = 0)
    STYLE
        COLOR 0 0 0
        OPACITY 0
    END
END

CLASS
    NAME "Low consensus (1/6)"
    EXPRESSION ([pixel] = 1)
    STYLE
        COLOR 222 235 247
        OPACITY 95
    END
END

CLASS
    NAME "Consensus (2/6)"
    EXPRESSION ([pixel] = 2)
    STYLE
        COLOR 198 219 239
        OPACITY 95
    END
END

CLASS
    NAME "Consensus (3/6)"
    EXPRESSION ([pixel] = 3)
    STYLE
        COLOR 158 202 225
        OPACITY 95
    END
END

CLASS
    NAME "Consensus (4/6)"
    EXPRESSION ([pixel] = 4)
    STYLE
        COLOR 107 174 214
        OPACITY 95
    END
END

CLASS
    NAME "High consensus (5/6)"
    EXPRESSION ([pixel] = 5)
    STYLE
        COLOR 49 130 189
        OPACITY 95
    END
END

CLASS
    NAME "Very high consensus (6/6)"
    EXPRESSION ([pixel] = 6)
    STYLE
        COLOR 8 81 156
        OPACITY 95
    END
END
